part of 'academy_english_advanced_models.dart';
/// A2 unit two: ten original thematic lessons with graded reading, listening and vocabulary.
abstract final class EnglishAdvancedA2UnitTwo {
  static const lessons = <EnglishAdvancedLesson>[
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:1,title:"A Room of Your Own",titleArabic:"غرفة تخصك",storyTitle:"A Room of Your Own",storyTitleArabic:"غرفة تخصك",paragraphs:<String>["Mariam moved into a shared house and met her new roommate near the hallway. The bedroom had a wooden wardrobe, a narrow closet, and a blue curtain beside the window. She carefully placed her books on a low bookshelf.","Her roommate noticed that a drawer was stuck and offered to repair it. They moved a small rug and hung a mirror frame on the wall. Mariam wanted a quiet place to study in the evening.","That night, she made her bed with a clean pillowcase and a soft duvet. She left a spare key on the bedside table and switched off the lamp. Her room already felt welcoming."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("roommate","شريك السكن"),EnglishAdvancedWord("hallway","ممر المنزل"),EnglishAdvancedWord("wardrobe","خزانة ملابس"),EnglishAdvancedWord("closet","خزانة صغيرة"),EnglishAdvancedWord("curtain","ستارة"),EnglishAdvancedWord("bookshelf","رف كتب"),EnglishAdvancedWord("drawer","درج"),EnglishAdvancedWord("rug","بساط"),EnglishAdvancedWord("mirror frame","إطار مرآة"),EnglishAdvancedWord("pillowcase","غطاء الوسادة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("duvet","لحاف"),EnglishAdvancedWord("spare key","مفتاح إضافي"),EnglishAdvancedWord("bedside table","طاولة سرير"),EnglishAdvancedWord("coat hook","علاقة معاطف"),EnglishAdvancedWord("laundry basket","سلة الغسيل"),EnglishAdvancedWord("curtain rail","قضيب ستارة"),EnglishAdvancedWord("floor mat","بساط أرضية"),EnglishAdvancedWord("storage box","صندوق تخزين"),EnglishAdvancedWord("light switch","مفتاح إضاءة"),EnglishAdvancedWord("window latch","مزلاج النافذة"),EnglishAdvancedWord("shelf bracket","حامل رف"),EnglishAdvancedWord("linen cupboard","خزانة بياضات"),EnglishAdvancedWord("desk organizer","منظم مكتب"),EnglishAdvancedWord("extension lead","وصلة كهربائية")],grammarTitle:"Possessive pronouns",grammarArabic:"نستعمل mine وyours بدل تكرار الاسم: This room is mine. ونستعمل my وyour قبل الأسماء.",grammarExamples:<String>["This room is mine.","Is the spare key yours?","The blue curtain is hers."],listening:"Hello, Mariam. The spare key is in the kitchen drawer, not on the bedside table. Your new study desk will arrive on Friday morning, so please keep the hallway clear for the delivery team. If you have any trouble opening the bedroom window, tell me this evening, and I will ask the landlord to check it.",listeningQuestion:"Where is the spare key?",listeningOptions:<String>["In the kitchen drawer","Under the rug","Inside the new desk"],listeningAnswer:0,readingQuestion:"What did Mariam hang on the wall?",readingOptions:<String>["A mirror frame","A bicycle wheel","A school timetable"],readingAnswer:0,writingCue:"Type the English term for: شريك السكن",writingAnswer:"roommate"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:2,title:"The Doctor's Advice",titleArabic:"نصيحة الطبيب",storyTitle:"The Doctor's Advice",storyTitleArabic:"نصيحة الطبيب",paragraphs:<String>["After a long day, Sami felt dizzy and developed a painful sore throat. He called the health clinic and arranged a consultation. The receptionist asked about his symptoms and told him to bring an insurance card.","At his appointment, the nurse measured his temperature and checked his pulse. The doctor noticed a fever and suggested warm drinks and plenty of rest. She warned Sami against exercising while he felt weak.","Back at home, Sami drank water and ate a bowl of soup. His sister helped him make a simple recovery plan, and two days later he felt much better. He knew when to contact the clinic again."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("dizzy","يشعر بالدوار"),EnglishAdvancedWord("painful sore throat","التهاب حلق مؤلم"),EnglishAdvancedWord("health clinic","عيادة صحية"),EnglishAdvancedWord("consultation","استشارة"),EnglishAdvancedWord("receptionist","موظف استقبال"),EnglishAdvancedWord("symptoms","أعراض"),EnglishAdvancedWord("insurance card","بطاقة تأمين"),EnglishAdvancedWord("nurse","ممرضة"),EnglishAdvancedWord("pulse","نبض"),EnglishAdvancedWord("fever","حمى")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("thermometer","ميزان حرارة"),EnglishAdvancedWord("appointment slip","ورقة موعد"),EnglishAdvancedWord("blood pressure","ضغط الدم"),EnglishAdvancedWord("checkup","فحص عام"),EnglishAdvancedWord("recovery plan","خطة تعافٍ"),EnglishAdvancedWord("medical history","تاريخ مرضي"),EnglishAdvancedWord("allergy test","اختبار حساسية"),EnglishAdvancedWord("first aid kit","حقيبة إسعافات"),EnglishAdvancedWord("hydration","ترطيب الجسم"),EnglishAdvancedWord("sick leave","إجازة مرضية"),EnglishAdvancedWord("waiting area","قاعة انتظار"),EnglishAdvancedWord("health record","سجل صحي"),EnglishAdvancedWord("follow-up visit","زيارة متابعة"),EnglishAdvancedWord("emergency contact","جهة اتصال طوارئ")],grammarTitle:"Should and shouldn't",grammarArabic:"نستخدم should للنصيحة وshouldn't لما يجب تجنبه، ويأتي بعدها الفعل دون to.",grammarExamples:<String>["You should drink water.","He shouldn't exercise today.","Should I call the clinic again?"],listening:"Good morning, this is the health clinic. Your appointment has moved from Tuesday morning to Wednesday afternoon. Please bring your insurance card and a list of medicines. If you still have a high temperature, tell the receptionist before entering the waiting area. Please call us before five if you need to change the appointment.",listeningQuestion:"When is the new appointment?",listeningOptions:<String>["Tuesday morning","Wednesday afternoon","Friday evening"],listeningAnswer:1,readingQuestion:"What did the doctor advise Sami to avoid?",readingOptions:<String>["Heavy exercise","Warm drinks","Sleeping at home"],readingAnswer:0,writingCue:"Type the English term for: يشعر بالدوار",writingAnswer:"dizzy"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:3,title:"A Recipe from Home",titleArabic:"وصفة من البيت",storyTitle:"A Recipe from Home",storyTitleArabic:"وصفة من البيت",paragraphs:<String>["Leena prepared her grandmother's handwritten recipe for dinner. She placed a mixing bowl on the counter and measured rice with a measuring cup. The instructions asked for cinnamon, cumin, and olive oil.","She chopped vegetables on a chopping board while her brother heated a saucepan. The kitchen filled with steam, and Leena gently stirred the sauce with a wooden spoon. She added a little seasoning before tasting it.","Everyone gathered around the table when dinner was ready. Her grandmother smiled and praised the meal. Leena wrote down the cooking time so she could prepare the same dish again next month."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("handwritten recipe","وصفة مكتوبة يدويًا"),EnglishAdvancedWord("mixing bowl","وعاء خلط"),EnglishAdvancedWord("measuring cup","كوب قياس"),EnglishAdvancedWord("cinnamon","قرفة"),EnglishAdvancedWord("cumin","كمون"),EnglishAdvancedWord("olive oil","زيت زيتون"),EnglishAdvancedWord("chopping board","لوح تقطيع"),EnglishAdvancedWord("saucepan","قدر صغير"),EnglishAdvancedWord("steam","بخار"),EnglishAdvancedWord("seasoning","توابل")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("wooden spoon","ملعقة خشبية"),EnglishAdvancedWord("pinch of salt","رشة ملح"),EnglishAdvancedWord("grater","مبشرة"),EnglishAdvancedWord("colander","مصفاة"),EnglishAdvancedWord("rolling pin","شوبك"),EnglishAdvancedWord("simmer","يطبخ على نار هادئة"),EnglishAdvancedWord("marinate","ينقع بالتوابل"),EnglishAdvancedWord("serving bowl","وعاء تقديم"),EnglishAdvancedWord("frying pan","مقلاة"),EnglishAdvancedWord("chopped herbs","أعشاب مقطعة"),EnglishAdvancedWord("kitchen scales","ميزان مطبخ"),EnglishAdvancedWord("tasting spoon","ملعقة تذوق"),EnglishAdvancedWord("oven mitt","قفاز فرن"),EnglishAdvancedWord("cooking timer","مؤقت طبخ")],grammarTitle:"Quantifiers: a little and a few",grammarArabic:"نستخدم a little مع غير المعدود مثل rice، وa few مع المعدود مثل tomatoes؛ وenough للكمية الكافية.",grammarExamples:<String>["Add a little olive oil.","We need a few tomatoes.","There is enough rice."],listening:"Welcome to the family cooking workshop. First, please rinse your rice and put one measuring cup on the table. Next, heat a little olive oil and add a small amount of cumin. Everyone will have twenty minutes to prepare the sauce. Do not add too much salt at the beginning because you can always add more later.",listeningQuestion:"What should participants do first?",listeningOptions:<String>["Taste the dishes","Rinse the rice","Add extra salt"],listeningAnswer:1,readingQuestion:"What did Leena write down after dinner?",readingOptions:<String>["The cooking time","The price of the meal","Her brother's address"],readingAnswer:0,writingCue:"Type the English term for: وصفة مكتوبة يدويًا",writingAnswer:"handwritten recipe"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:4,title:"A Bicycle Repair",titleArabic:"إصلاح دراجة",storyTitle:"A Bicycle Repair",storyTitleArabic:"إصلاح دراجة",paragraphs:<String>["Yusuf discovered that his bicycle chain had slipped from the gear. The rear wheel made a strange noise, and the brake lever felt loose. He pushed his bike to a repair workshop near the park.","The mechanic lifted the bike onto a repair stand and checked the chain. He tightened a bolt with a spanner and measured the tire pressure. Yusuf watched carefully so he could recognize the problem next time.","Before leaving, Yusuf tested the repaired brakes in a quiet car park. He put on his helmet and thanked the mechanic for explaining every step. He knew the road would be safer now."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("bicycle chain","سلسلة دراجة"),EnglishAdvancedWord("gear","ترس"),EnglishAdvancedWord("rear wheel","العجلة الخلفية"),EnglishAdvancedWord("brake lever","ذراع فرامل"),EnglishAdvancedWord("repair workshop","ورشة إصلاح"),EnglishAdvancedWord("mechanic","ميكانيكي"),EnglishAdvancedWord("repair stand","حامل صيانة"),EnglishAdvancedWord("bolt","مسمار تثبيت"),EnglishAdvancedWord("spanner","مفتاح ربط"),EnglishAdvancedWord("tire pressure","ضغط الإطار")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("brake cable","سلك مكابح"),EnglishAdvancedWord("helmet strap","حزام خوذة"),EnglishAdvancedWord("inner tube","أنبوب إطار"),EnglishAdvancedWord("pedal","دواسة"),EnglishAdvancedWord("handlebar grip","مقبض مقود"),EnglishAdvancedWord("chain oil","زيت السلسلة"),EnglishAdvancedWord("puncture patch","رقعة ثقب"),EnglishAdvancedWord("wheel spoke","سلك عجلة"),EnglishAdvancedWord("reflector","عاكس ضوء"),EnglishAdvancedWord("air pump","مضخة هواء"),EnglishAdvancedWord("tool kit","عدة أدوات"),EnglishAdvancedWord("safety inspection","فحص سلامة"),EnglishAdvancedWord("cycle lane","مسار دراجات"),EnglishAdvancedWord("punctured tire","إطار مثقوب")],grammarTitle:"Mustn't versus don't have to",grammarArabic:"نستخدم mustn't للمنع وdon't have to لعدم الضرورة. يأتي بعد الأفعال المساعدة الفعل الأساسي.",grammarExamples:<String>["You mustn't ride with broken brakes.","You don't have to buy a new wheel.","You have to wear a helmet."],listening:"Hello, this is Green Street Bicycle Repairs. We have checked your bicycle, but the rear brake cable needs replacing. The new part will arrive tomorrow morning, so please collect the bicycle after lunch. You do not need a new wheel. Bring your receipt when you come and we will check your tire pressure without charging extra.",listeningQuestion:"Why is the bicycle not ready today?",listeningOptions:<String>["A brake cable part is missing","The entire wheel was stolen","The shop has closed forever"],listeningAnswer:0,readingQuestion:"Where did Yusuf test the brakes?",readingOptions:<String>["In a quiet car park","On a busy highway","Inside the classroom"],readingAnswer:0,writingCue:"Type the English term for: سلسلة دراجة",writingAnswer:"bicycle chain"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:5,title:"The Pet Adoption",titleArabic:"تبني حيوان أليف",storyTitle:"The Pet Adoption",storyTitleArabic:"تبني حيوان أليف",paragraphs:<String>["Salma visited a rescue center hoping to adopt a kitten. A volunteer showed her a suitable home checklist and an adoption form. The center also explained what veterinary care each animal needed.","Salma played with the kitten using a toy mouse and watched it fall asleep. The volunteer showed her its vaccination record and explained how to transport the animal in a safe animal carrier.","The next day Salma returned with her family. She had prepared a scratching post, water, and a quiet sleeping area. She understood that caring for an animal was a long-term responsibility."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("rescue center","مركز إنقاذ"),EnglishAdvancedWord("adopt","يتبنى"),EnglishAdvancedWord("kitten","هريرة"),EnglishAdvancedWord("suitable home checklist","قائمة منزل مناسب"),EnglishAdvancedWord("adoption form","استمارة تبني"),EnglishAdvancedWord("veterinary care","رعاية بيطرية"),EnglishAdvancedWord("toy mouse","لعبة فأر"),EnglishAdvancedWord("vaccination record","سجل التطعيم"),EnglishAdvancedWord("animal carrier","حاملة حيوانات"),EnglishAdvancedWord("scratching post","عمود خدش")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("pet food","طعام حيوانات"),EnglishAdvancedWord("feeding schedule","جدول تغذية"),EnglishAdvancedWord("animal welfare","رفاه الحيوان"),EnglishAdvancedWord("microchip","شريحة تعريف"),EnglishAdvancedWord("leash","مقود"),EnglishAdvancedWord("collar tag","بطاقة طوق"),EnglishAdvancedWord("litter tray","صندوق رمل"),EnglishAdvancedWord("pet sitter","جليس الحيوانات"),EnglishAdvancedWord("behavior training","تدريب سلوكي"),EnglishAdvancedWord("grooming brush","فرشاة عناية"),EnglishAdvancedWord("pet insurance","تأمين حيوانات"),EnglishAdvancedWord("daily walk","نزهة يومية"),EnglishAdvancedWord("safe enclosure","مكان مغلق آمن"),EnglishAdvancedWord("animal passport","جواز حيوان")],grammarTitle:"Can and could for polite requests",grammarArabic:"نستخدم can للسؤال عن الإذن، وcould لصياغة طلب ألطف؛ ولا نضيف to بعدهما.",grammarExamples:<String>["Can I adopt this kitten?","Could you explain the routine?","The kitten can climb."],listening:"Thank you for contacting the animal rescue center. Visitors are welcome on Saturday between ten and two. Please bring identification and ask everyone in your home before choosing a pet. A volunteer can explain the animals' feeding needs and medical records. We can lend you a carrier, but you should prepare your own food and sleeping supplies.",listeningQuestion:"What should visitors do before adopting?",listeningOptions:<String>["Ask their household","Arrive after midnight","Buy an expensive dog"],listeningAnswer:0,readingQuestion:"What did the volunteer show Salma?",readingOptions:<String>["A vaccination record","A train map","A school report"],readingAnswer:0,writingCue:"Type the English term for: مركز إنقاذ",writingAnswer:"rescue center"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:6,title:"An Invitation to Tea",titleArabic:"دعوة إلى الشاي",storyTitle:"An Invitation to Tea",storyTitleArabic:"دعوة إلى الشاي",paragraphs:<String>["Hala received a handwritten invitation for afternoon tea from a neighbor. She checked the address, starting time, and request to confirm attendance. She offered to bring homemade biscuits for the other guests.","She arrived at the front porch and rang the doorbell. Her host welcomed her and showed a table covered with a patterned tablecloth. A teapot and sugar bowl stood beside the small cups.","During the friendly gathering, Hala met two new neighbors and heard about their hobbies. She thanked her host and promised to invite everyone to her home on another weekend."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("handwritten invitation","دعوة مكتوبة يدويًا"),EnglishAdvancedWord("confirm attendance","يؤكد الحضور"),EnglishAdvancedWord("homemade biscuits","بسكويت منزلي"),EnglishAdvancedWord("front porch","شرفة أمامية"),EnglishAdvancedWord("doorbell","جرس الباب"),EnglishAdvancedWord("host","مضيف"),EnglishAdvancedWord("patterned tablecloth","مفرش مزخرف"),EnglishAdvancedWord("teapot","إبريق شاي"),EnglishAdvancedWord("sugar bowl","وعاء السكر"),EnglishAdvancedWord("friendly gathering","تجمع ودي")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("refreshments","مرطبات"),EnglishAdvancedWord("tea leaves","أوراق الشاي"),EnglishAdvancedWord("herbal infusion","منقوع أعشاب"),EnglishAdvancedWord("serving tray","صينية تقديم"),EnglishAdvancedWord("small talk","حديث خفيف"),EnglishAdvancedWord("polite refusal","اعتذار مهذب"),EnglishAdvancedWord("thank-you note","رسالة شكر"),EnglishAdvancedWord("social etiquette","آداب اجتماعية"),EnglishAdvancedWord("guest list","قائمة ضيوف"),EnglishAdvancedWord("seating arrangement","ترتيب جلوس"),EnglishAdvancedWord("doorstep","عتبة باب"),EnglishAdvancedWord("homemade snack","وجبة منزلية خفيفة"),EnglishAdvancedWord("pleasant company","صحبة ممتعة"),EnglishAdvancedWord("return invitation","دعوة مقابلة")],grammarTitle:"Would you like to for invitations",grammarArabic:"ندعو الآخرين باستخدام Would you like to ...? ونوافق بأسلوب لطيف بـ I'd love to.",grammarExamples:<String>["Would you like to come for tea?","I'd love to. Thank you.","I'm sorry, but I cannot come."],listening:"Hello, Hala. I am calling to confirm our tea gathering on Saturday. Please arrive at four, not three, because I need more time to prepare. You do not have to bring anything, although homemade snacks are welcome. The entrance is through the front porch beside the flowerpot. We look forward to seeing you and introducing you to our neighbors.",listeningQuestion:"When should Hala arrive?",listeningOptions:<String>["At three","At four","At six"],listeningAnswer:1,readingQuestion:"Who did Hala meet at the gathering?",readingOptions:<String>["New neighbors","A police officer","A train driver"],readingAnswer:0,writingCue:"Type the English term for: دعوة مكتوبة يدويًا",writingAnswer:"handwritten invitation"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:7,title:"A Language Exchange",titleArabic:"تبادل لغوي",storyTitle:"A Language Exchange",storyTitleArabic:"تبادل لغوي",paragraphs:<String>["Omar joined a language exchange at the learning center. The first session started with a name badge and a short introduction. Everyone met a conversation partner and chose a discussion topic.","His partner asked about childhood memories and encouraged him to ask a follow-up question. Omar felt nervous about a grammar mistake, but the leader showed him helpful flashcards.","At the end, each student wrote one learning goal for the next week. Omar promised to practice at home and felt more confident speaking with another learner."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("language exchange","تبادل لغوي"),EnglishAdvancedWord("learning center","مركز تعلم"),EnglishAdvancedWord("name badge","بطاقة اسم"),EnglishAdvancedWord("introduction","تعريف بالنفس"),EnglishAdvancedWord("conversation partner","شريك محادثة"),EnglishAdvancedWord("discussion topic","موضوع نقاش"),EnglishAdvancedWord("follow-up question","سؤال متابعة"),EnglishAdvancedWord("grammar mistake","خطأ نحوي"),EnglishAdvancedWord("flashcards","بطاقات تعليمية"),EnglishAdvancedWord("learning goal","هدف تعلم")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("study circle","مجموعة دراسة"),EnglishAdvancedWord("speaking turn","دور التحدث"),EnglishAdvancedWord("fluency practice","تدريب طلاقة"),EnglishAdvancedWord("phrase notebook","دفتر عبارات"),EnglishAdvancedWord("language barrier","حاجز لغة"),EnglishAdvancedWord("peer feedback","ملاحظات الزملاء"),EnglishAdvancedWord("practice partner","شريك تدريب"),EnglishAdvancedWord("listening task","مهمة استماع"),EnglishAdvancedWord("role-playing exercise","تمرين أدوار"),EnglishAdvancedWord("reading aloud","قراءة جهرية"),EnglishAdvancedWord("daily revision","مراجعة يومية"),EnglishAdvancedWord("corrective feedback","تصحيح بنّاء"),EnglishAdvancedWord("speaking confidence","ثقة التحدث"),EnglishAdvancedWord("group facilitator","ميسر مجموعة")],grammarTitle:"Present perfect: ever and never",grammarArabic:"نسأل عن الخبرة باستخدام Have you ever... ونستخدم I have never... للتعبير عن تجربة لم تحدث من قبل.",grammarExamples:<String>["Have you ever joined a club?","I have never used flashcards.","She has practiced with her partner."],listening:"Welcome to the language exchange. Our session starts at six fifteen with a short introduction. For twenty minutes, speak English with your partner and ask follow-up questions. After a break, you may change partners or practice a different language. Before going home, write one clear learning goal and discuss it with the group leader.",listeningQuestion:"What may learners do after the break?",listeningOptions:<String>["Change partner or language","Leave immediately","Take a final examination"],listeningAnswer:0,readingQuestion:"What made Omar feel less nervous?",readingOptions:<String>["Helpful flashcards and practice","A large prize","A school holiday"],readingAnswer:0,writingCue:"Type the English term for: تبادل لغوي",writingAnswer:"language exchange"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:8,title:"The Lost Phone",titleArabic:"الهاتف المفقود",storyTitle:"The Lost Phone",storyTitleArabic:"الهاتف المفقود",paragraphs:<String>["Reem noticed that her mobile phone was missing from her coat pocket. She looked inside her handbag and asked the bus conductor whether someone had found a lost device.","The conductor recommended the lost property office. There, a worker asked about the phone case and the screen lock. Another passenger had returned the phone, and Reem showed her student card to collect it.","Reem felt relieved. She activated a location feature and saved an emergency contact number. She promised to keep her phone safe on future trips."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("mobile phone","هاتف محمول"),EnglishAdvancedWord("coat pocket","جيب معطف"),EnglishAdvancedWord("handbag","حقيبة يد"),EnglishAdvancedWord("bus conductor","محصل الحافلة"),EnglishAdvancedWord("lost device","جهاز مفقود"),EnglishAdvancedWord("lost property office","مكتب مفقودات"),EnglishAdvancedWord("phone case","غطاء هاتف"),EnglishAdvancedWord("screen lock","قفل شاشة"),EnglishAdvancedWord("student card","بطاقة طالب"),EnglishAdvancedWord("location feature","خاصية تحديد الموقع")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("emergency contact number","رقم اتصال طارئ"),EnglishAdvancedWord("phone charger","شاحن هاتف"),EnglishAdvancedWord("portable battery","بطارية متنقلة"),EnglishAdvancedWord("digital backup","نسخة احتياطية رقمية"),EnglishAdvancedWord("serial number","رقم تسلسلي"),EnglishAdvancedWord("recovery code","رمز استعادة"),EnglishAdvancedWord("notification sound","صوت إشعار"),EnglishAdvancedWord("customer helpline","خدمة العملاء"),EnglishAdvancedWord("touchscreen","شاشة لمس"),EnglishAdvancedWord("device settings","إعدادات الجهاز"),EnglishAdvancedWord("signal strength","قوة الإشارة"),EnglishAdvancedWord("privacy setting","إعداد خصوصية"),EnglishAdvancedWord("data connection","اتصال بيانات"),EnglishAdvancedWord("missing item report","بلاغ مفقود")],grammarTitle:"Present perfect with just and already",grammarArabic:"نستخدم have/has + التصريف الثالث مع just وalready للحدث الأخير المرتبط بالحاضر.",grammarExamples:<String>["I have just found my phone.","She has already called the office.","Have they returned it yet?"],listening:"You have reached the city bus lost property office. A black phone was found this morning on route fourteen. If you think it is yours, please bring identification before four thirty. You will need to describe the case and show that you can unlock the screen. Items not collected by Friday will be moved to our central office.",listeningQuestion:"What should owners bring?",listeningOptions:<String>["Proof of identity","New headphones","A bus driver"],listeningAnswer:0,readingQuestion:"Who handed in Reem's phone?",readingOptions:<String>["Another passenger","Her teacher","Her brother"],readingAnswer:0,writingCue:"Type the English term for: هاتف محمول",writingAnswer:"mobile phone"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:9,title:"Buying a Birthday Gift",titleArabic:"شراء هدية عيد ميلاد",storyTitle:"Buying a Birthday Gift",storyTitleArabic:"شراء هدية عيد ميلاد",paragraphs:<String>["Amal wanted a birthday gift for her brother, but she had a small spending limit. At a craft market she compared a handmade bookmark with a leather wallet and asked a shop assistant about the gift box.","She chose a personalized key ring and asked for wrapping paper and a greeting card. The shop assistant showed her the price before she paid by contactless payment.","At the family party her brother loved the gift. Amal learned that a personal message matters more than an expensive present. She was happy with her careful choice."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("birthday gift","هدية عيد ميلاد"),EnglishAdvancedWord("spending limit","حد الإنفاق"),EnglishAdvancedWord("craft market","سوق الحرف"),EnglishAdvancedWord("handmade bookmark","علامة كتاب يدوية"),EnglishAdvancedWord("leather wallet","محفظة جلدية"),EnglishAdvancedWord("shop assistant","موظف مبيعات"),EnglishAdvancedWord("gift box","علبة هدية"),EnglishAdvancedWord("personalized key ring","حلقة مفاتيح مخصصة"),EnglishAdvancedWord("wrapping paper","ورق تغليف"),EnglishAdvancedWord("greeting card","بطاقة تهنئة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("contactless payment","دفع دون تماس"),EnglishAdvancedWord("price label","بطاقة سعر"),EnglishAdvancedWord("special offer","عرض خاص"),EnglishAdvancedWord("personal message","رسالة شخصية"),EnglishAdvancedWord("gift receipt","إيصال هدية"),EnglishAdvancedWord("exchange policy","سياسة استبدال"),EnglishAdvancedWord("cash discount","خصم نقدي"),EnglishAdvancedWord("shopping bag","كيس تسوق"),EnglishAdvancedWord("display cabinet","خزانة عرض"),EnglishAdvancedWord("craftsmanship","مهارة حرفية"),EnglishAdvancedWord("product quality","جودة المنتج"),EnglishAdvancedWord("engraving","نقش"),EnglishAdvancedWord("gift ribbon","شريط هدية"),EnglishAdvancedWord("purchase limit","حد شراء")],grammarTitle:"Comparatives with more, less and as...as",grammarArabic:"نستخدم more وless للمقارنة، وas ... as للمساواة بين شيئين.",grammarExamples:<String>["This gift is more personal.","The key ring is less expensive.","This gift is as useful as that one."],listening:"Welcome to the Handmade Gift Shop. This week you can receive free gift wrapping with any personalized key ring. If you order engraving before two o'clock, your gift will be ready by six today. Please keep the receipt for exchanges within seven days. Personalized products cannot be refunded unless they have a manufacturing fault.",listeningQuestion:"When is the key ring ready if ordered early?",listeningOptions:<String>["By six today","Next month","The following Saturday"],listeningAnswer:0,readingQuestion:"Why was Amal's brother happy?",readingOptions:<String>["The gift was personal","The gift was very expensive","He received a car"],readingAnswer:0,writingCue:"Type the English term for: هدية عيد ميلاد",writingAnswer:"birthday gift"),
EnglishAdvancedLesson(level:'A2',unitNumber:2,number:10,title:"A Weekend by the Sea",titleArabic:"عطلة عند البحر",storyTitle:"A Weekend by the Sea",storyTitleArabic:"عطلة عند البحر",paragraphs:<String>["Two friends booked a small guesthouse near the harbor wall for a weekend trip. Their itinerary included a coastal path, a boat trip, and a meal by the sea. They packed jackets because of the cool sea breeze.","On Saturday they watched boats in the marina and climbed a hill to see the lighthouse. A guide showed them a quiet cove beside the cliffs, but the waves were too strong for swimming.","On Sunday they enjoyed a picnic and returned home by bus. They were pleased that they had followed their plan while finding time for unexpected discoveries."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("guesthouse","بيت ضيافة"),EnglishAdvancedWord("harbor wall","جدار ميناء"),EnglishAdvancedWord("itinerary","برنامج رحلة"),EnglishAdvancedWord("coastal path","ممشى ساحلي"),EnglishAdvancedWord("boat trip","رحلة بحرية"),EnglishAdvancedWord("sea breeze","نسيم بحري"),EnglishAdvancedWord("marina","مرسى"),EnglishAdvancedWord("lighthouse","منارة"),EnglishAdvancedWord("cove","خليج صغير"),EnglishAdvancedWord("cliffs","جروف صخرية")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("tide timetable","جدول المد"),EnglishAdvancedWord("shoreline","خط الساحل"),EnglishAdvancedWord("seashell collection","مجموعة أصداف"),EnglishAdvancedWord("beach towel","منشفة شاطئ"),EnglishAdvancedWord("sun protection","وقاية شمسية"),EnglishAdvancedWord("fishing pier","رصيف صيد"),EnglishAdvancedWord("lifeguard station","مركز منقذين"),EnglishAdvancedWord("rock pool","بركة صخرية"),EnglishAdvancedWord("coastal village","قرية ساحلية"),EnglishAdvancedWord("waterproof bag","حقيبة مقاومة للماء"),EnglishAdvancedWord("wave forecast","توقعات أمواج"),EnglishAdvancedWord("beach access","مدخل شاطئ"),EnglishAdvancedWord("return crossing","رحلة العودة البحرية"),EnglishAdvancedWord("sunset viewpoint","منصة مشاهدة الغروب")],grammarTitle:"Going to and will for future plans",grammarArabic:"نستخدم going to لخطط قررناها مسبقًا، وwill للقرارات أو التوقعات التي نعلنها الآن.",grammarExamples:<String>["We're going to stay by the sea.","I think we will enjoy the trip.","If it rains, we will visit a museum."],listening:"Here is the seaside visitor center weekend forecast. Saturday morning will be windy near the cliffs, so the coastal path may be uncomfortable for younger children. Boat trips may start at two if the water becomes calm. Sunday will be warmer, with the picnic area open all afternoon. Always check the tide timetable before walking near rocks.",listeningQuestion:"When may the boats start?",listeningOptions:<String>["At two if it is calm","At midnight","Next Friday"],listeningAnswer:0,readingQuestion:"Why did the friends avoid swimming?",readingOptions:<String>["The waves were strong","They forgot their shoes","The beach was locked"],readingAnswer:0,writingCue:"Type the English term for: بيت ضيافة",writingAnswer:"guesthouse")
  ];
}
